      } else {
        $str.Substring( 0, $max - 1 ) + '…';
      }
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 >> "C:\Windows\Setup\Scripts\DefaultUser.log";

$scripts = @(
	{
		Set-ItemProperty -LiteralPath 'Registry::HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoLogonCount' -Type 'DWord' -Force -Value 0;
	};
    {
        $logPath = "C:\EnableWinRM.log";
        Start-Transcript -Path $logPath -Append;

        try {
            Start-Service WinRM;
            Set-Service -Name WinRM -StartupType Automatic;
            # Keep the initial network profile private when possible, but do not rely on it for WinRM reachability.
            Get-NetConnectionProfile | Where-Object {$_.NetworkCategory -eq 'Public'} | Set-NetConnectionProfile -NetworkCategory Private;
            Set-Item -Path WSMan:\localhost\Service\AllowUnencrypted -Value $true;
            Set-Item -Path WSMan:\localhost\Service\Auth\Basic -Value $true;
            Enable-PSRemoting -SkipNetworkProfileCheck -Force;
            # Keep WinRM reachable even if Windows later reclassifies the NIC as Public.
            # Attack surface note: this keeps WinRM Basic over HTTP exposed on TCP/5985 for all
            # firewall profiles and remote addresses. Combined with the unattended Administrator
            # credential configured earlier in this file, that is broader exposure than a
            # private-network-only rule and should only be used on trusted build networks.
            # A safer provisioning approach is planned for future releases.
            $winRmFirewallRuleName = 'DevAlchemy-WinRM-HTTP-In-TCP';
            if (-not (Get-NetFirewallRule -Name $winRmFirewallRuleName -ErrorAction SilentlyContinue)) {
                New-NetFirewallRule -Name $winRmFirewallRuleName -DisplayName 'DevAlchemy WinRM HTTP' -Enabled True -Profile Any -Direction Inbound -Action Allow -Protocol TCP -LocalPort 5985 -RemoteAddress Any;
            } else {
                Set-NetFirewallRule -Name $winRmFirewallRuleName -Enabled True -Profile Any -Action Allow;
            }
        } catch {
            Write-Error "An error occurred while enabling WinRM: $_";
        }

        Stop-Transcript;
    };
);

& {
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Activity 'Running scripts to finalize your Windows installation. Do not close this window.' -PercentComplete $complete;
